----------------------------------------------------------------------
-- Amazing Hub - the item catalogue on WoW: Forever (Amazing Forever Guild Pack 0.7.0; our own file, not upstream)
--
-- Data/ItemCatalog.lua (GENERATED by tools/build-catalog.py from Blizzard's game data) lists every item a player may
-- wish for: id = { name, quality, slot, item level }. Here it goes into the wishlist's catalogue (Modules/
-- WishlistSystem.lua: Wishlist.catalog, which retail fills from the Encounter Journal). So the wishlist's add box
-- and the hub's search find any of them by name, even items this client has never seen (ItemFacts falls back
-- to the catalogue's name). Forever has no Encounter Journal, so there is no boss or raid for an item.
-- On other clients the table is dropped unread. The global goes away either way.
--
-- Copied in by tools/rebrand-hub.py from addon/hub-extra/; edit it there.
----------------------------------------------------------------------
local cat = AmazingHubItemCatalog
AmazingHubItemCatalog = nil

local W = AmazingHub.Wishlist
local client = AmazingHub.Client
if not (W and type(cat) == "table" and type(cat.items) == "table" and client and client.game == "FOREVER") then return end

W.catalog = W.catalog or {}
local n = 0
for id, e in pairs(cat.items) do
    if type(id) == "number" and type(e) == "table" and type(e[1]) == "string" and not W.catalog[id] then
        W.catalog[id] = { name = e[1], quality = e[2], slot = e[3], ilvl = e[4] }
        n = n + 1
    end
end
W.catalogBuild, W.catalogCount = cat.build, n
